fields.InputDefinition:
{
  "goal": "In the Issues app, find issue MC-0031: search or filter the issue list for 'MC-0031' (or 'Gorsemere'), then open the issue. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/issues",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
